-- lua/config/colorscheme.lua
-- Base colorscheme plus the palette overrides from lua/colors.lua.
--
-- lua/theme.lua holds the palette and is regenerated by
-- dotthemes/theme-picker.sh -- don't move or hand-edit it.

vim.cmd("colorscheme oxocarbon")

require("colors").apply()
-- Must run after the colorscheme, which sets its own terminal_color_*.
require("config.terminal").apply()

-- Re-apply custom highlights after any colorscheme change
vim.api.nvim_create_autocmd("ColorScheme", {
	pattern = "*",
	callback = function()
		require("colors").apply()
		require("config.terminal").apply()
	end,
})
